/**
 * Icon ids that share another weapon's silhouette: generic family ids map
 * to their most iconic representative, and spelling aliases collapse.
 */
export const WEAPON_SILHOUETTE_ALIASES: Record<string, string> = {
  "fiveseven": "fn57",
  "mg": "m249",
  "pistol": "usp",
  "rifle": "ak47",
  "shotgun": "xm1014",
  "smg": "mp5",
  "sniper": "awp",
};

/** Resolve an icon id to the silhouette key, following aliases. */
export function resolveSilhouetteId(iconId: string): string | undefined {
  if (WEAPON_SILHOUETTES[iconId]) return iconId;
  const alias = WEAPON_SILHOUETTE_ALIASES[iconId];
  if (alias) return alias;
  if (iconId.includes('knife') || iconId.includes('karambit') || iconId.includes('butterfly')) return 'knife';
  if (iconId.includes('snip')) return 'awp';
  if (iconId.includes('shot')) return 'xm1014';
  if (iconId.includes('glov')) return 'gloves';
  if (iconId.includes('scope') || iconId.includes('aug')) return 'aug';
  return 'ak47';
}
